1	// Scope-blind mechanism (no policy, no scope knowledge): given a built context
2	// and the discovered packs, run the ACTIVE packs' rules that a caller-supplied
3	// predicate admits, and return their findings. The world and work runners each
4	// call this with their own `includeRule` — this file never names a scope, so
5	// the two runners stay independent of each other while sharing the walk.
6	import { runRule } from './helpers/work.mjs';
7	import { isActive } from '../pack_loader/pack-registry.mjs';
8	
9	// A pack's contributedRules seam: the pack interprets the contributions other
10	// packs address to it on their manifests (`contributes`), returning first-class
11	// rules — how packs compose through declaration + configuration instead of
12	// importing each other's code. Isolated per pack, like manifest loading: one
13	// broken seam (a consumer-authored local pack's, say) must not sink the run.
14	// `onError` lets a caller turn a broken seam into a finding; passing none
15	// swallows it (a runner that doesn't own config diagnostics stays quiet).
16	export function contributedRules(pack, fromPacks, onError = null) {
17	  try { return pack.contributedRules?.(fromPacks) ?? []; }
18	  catch (e) { onError?.(e); return []; }
19	}
20	
21	// Every finding from the active packs' rules that `includeRule` admits. A rule
22	// turned `off` in settings is skipped. `onContributeError(pack, err)` is invoked
23	// when a pack's contributedRules seam throws (the caller decides whether that
24	// becomes a finding).
25	export function runActivePackRules(ctx, packs, { includeRule, onContributeError = null }) {
26	  const findings = [];
27	  // Expose the discovered packs to any rule that reasons about pack metadata
28	  // (e.g. the adoption-interview hygiene check reads each active pack's declared
29	  // questions) — checks run synchronously and can't re-discover packs themselves.
30	  ctx.packs = packs;
31	  const activePacks = packs.filter((p) => isActive(p, ctx.config));
32	  for (const pack of activePacks) {
33	    const contributed = contributedRules(pack, activePacks,
34	      onContributeError ? (e) => onContributeError(pack, e) : null);
35	    for (const rule of [...(pack.rules ?? []), ...(pack.skillChecks ?? []), ...contributed]) {
36	      if (!includeRule(rule)) continue;
37	      if (ctx.config.rules[rule.id] === 'off') continue;
38	      findings.push(...runRule(rule, ctx));
39	    }
40	  }
41	  return findings;
42	}
43

1	import { finding } from '../../engine/checks/helpers/findings.mjs';
2	
3	const LIMIT = 200;
4	
5	// Converted from authoring-agent-docs: "Target under 200 lines per CLAUDE.md;
6	// longer files consume more context and reduce adherence." Directional → advisory.
7	const rule = {
8	  id: 'claude-md-length',
9	  severity: 'advisory',
10	  description: 'A CLAUDE.md over ~200 lines costs context and reduces adherence',
11	  doc: 'skills/authoring-agent-docs/SKILL.md',
12	  why: 'everything in CLAUDE.md loads every session; past ~200 lines it crowds out the rules that matter',
13	
14	  run(ctx) {
15	    // Root CLAUDE.md only — the one that definitely loads every session. A nested
16	    // or fixture CLAUDE.md may never load, so flagging its length would be a false
17	    // positive (an adversarial-mining finding).
18	    const text = ctx.read('CLAUDE.md');
19	    if (text === null) return [];
20	    const lines = text.split('\n').length;
21	    if (lines <= LIMIT) return [];
22	    return [finding(rule, {
23	      file: 'CLAUDE.md', line: LIMIT + 1,
24	      what: `${lines} lines (target under ${LIMIT})`,
25	      fix: 'move multi-step procedures to skills and part-of-repo rules to path-scoped packs; keep CLAUDE.md to always-true facts',
26	    })];
27	  },
28	};
29	
30	export default rule;
31

1	import { dirname, join, normalize } from 'node:path';
2	import { humanTurns, assistantTextAfter, classificationLine, classesIn } from './session-transcript.mjs';
3	import { addedLines } from './line-scanning.mjs';
4	import { extractLinks } from './markdown.mjs';
5	
6	// The fluent check-the-work surface over ctx. Every accessor is null-safe — no
7	// transcript, no merge-base, an empty branch all yield empty results — so a rule
8	// reads as one chain with no guard ladders. Mechanism only: a rule still owns
9	// its patterns, file filters, and failure text.
10	//
11	// A rule declaring `scope: 'work'` receives this object as its `run` argument
12	// (runRule dispatches); check-the-world rules keep the raw ctx until a fluent
13	// world object exists. The raw surface a work rule still needs (files, read,
14	// exists, …) is delegated here, so a work rule — and the structural helpers it
15	// calls, e.g. findExtensionManifest — never touches ctx itself.
16	export const work = (ctx) => new Work(ctx);
17	
18	// The single dispatch seam: the runner and every rule test invoke rules through
19	// this, so a rule's scope decides its context in exactly one place. Extra args
20	// pass through (some rules take test-only options after the context).
21	export const runRule = (rule, ctx, ...args) => rule.run(rule.scope === 'work' ? work(ctx) : ctx, ...args);
22	
23	// Null-object for "no such turn": every accessor answers emptily, so a chain
24	// ending in .last() never needs an existence guard before its predicates.
25	const NO_TURN = {
26	  exists: false, text: '', timestamp: null,
27	  excerpt: () => '', reply: () => '', classified: () => false,
28	  classes: () => new Set(), time: () => 0,
29	};
30	
31	class Turn {
32	  constructor(entries, { index, timestamp, text }) {
33	    this.entries = entries;
34	    this.index = index;
35	    this.timestamp = timestamp;
36	    this.text = text;
37	    this.exists = true;
38	  }
39	
40	  excerpt(n) { return this.text.replace(/\s+/g, ' ').slice(0, n); }
41	  reply() { return assistantTextAfter(this.entries, this.index); }
42	  classified() { return classificationLine(this.reply()) !== null; }
43	  classes() { return classesIn(classificationLine(this.reply())); }
44	  time() { return Date.parse(this.timestamp ?? '') || 0; }
45	}
46	
47	// Array subclass so filter/map stay chainable and .last() survives them.
48	class Turns extends Array {
49	  last() { return this.length ? this[this.length - 1] : NO_TURN; }
50	}
51	
52	class Conversation {
53	  constructor(entries) { this.entries = entries ?? []; }
54	
55	  ownerTurns() {
56	    const turns = new Turns();
57	    for (const t of humanTurns(this.entries)) turns.push(new Turn(this.entries, t));
58	    return turns;
59	  }
60	}
61	
62	class Work {
63	  constructor(ctx) { this.ctx = ctx; }
64	
65	  get branch() { return this.ctx.branch; }
66	  get baseRef() { return this.ctx.baseRef; }
67	  get commits() { return this.ctx.commits; }
68	  get files() { return this.ctx.files; }
69	  get changedFiles() { return this.ctx.changedFiles; }
70	  get tracked() { return this.ctx.tracked; }
71	  read(path) { return this.ctx.read(path); }
72	  readBase(path) { return this.ctx.readBase(path); }
73	  exists(path) { return this.ctx.exists(path); }
74	  packConfig(id) { return this.ctx.config?.packConfig?.[id]; }
75	
76	  conversation() { return new Conversation(this.ctx.conversation()); }
77	
78	  addedLines(files) { return addedLines(this.ctx, files ?? this.ctx.changedFiles); }
